// Get inputs passed into this sub-workflow
const triggerInput = $('When Executed by Another Workflow').first().json;
const planId = triggerInput.plan_id ?? null;
const serviceCode = triggerInput.service_code ?? null;

// Parsed benefits.json from the previous node
const benefits = $input.first().json.data;

// Validate input
if (!planId || !serviceCode) {
  return [
    {
      json: {
        tool: 'BENEFITS',
        status: 'INVALID_INPUT',
        plan_id: planId,
        service_code: serviceCode,
        data: null,
        error: 'plan_id and service_code are required'
      }
    }
  ];
}

// Find the requested plan benefit
const benefit = benefits.find(
  (record) =>
    record.plan_id === planId &&
    record.service_code === serviceCode
);

// Benefit not found
if (!benefit) {
  return [
    {
      json: {
        tool: 'BENEFITS',
        status: 'NOT_FOUND',
        plan_id: planId,
        service_code: serviceCode,
        data: null,
        error: 'Benefit not found'
      }
    }
  ];
}

// Return only fields useful to servicing
return [
  {
    json: {
      tool: 'BENEFITS',
      status: 'SUCCESS',
      plan_id: benefit.plan_id,
      service_code: benefit.service_code,
      data: {
        benefit_id: benefit.benefit_id,
        service_name: benefit.service_name,
        covered: benefit.covered,
        prior_authorization_required:
          benefit.prior_authorization_required,
        network_requirement: benefit.network_requirement
      },
      error: null
    }
  }
];
